const engName = n => ENGN[n] || n;
const esc = s => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const chip = n => `<span class="c k-${TYPE[n] || 'eff'}">${esc(n)}</span>`;
const rich = t => esc(t).replace(/\[([^\]]+)\]/g, (_, n) => chip(n));
const chipText = t => esc(t).replace(/(Mediclius|Desirae|Diactorus|Non-Finito|Junora|Nerva|Impasto|Citrinitas|Finite and Infinite|Corruption and Purification|Magician of Dark Chaos|Medius|Mind Shuffle|S:P Little Knight|Nervedo|Requiem|Sequence|Vidolia|Theorealized Medius)/g, m => `<span class="c k-${TYPE[m]}">${m}</span>`);
const GROUPS = [['Power Patron', ['med','tm','nerv','juno','vidm','tre','ter','vidolia','lib','pl','sw']], ['Ars Magna / Artmage', ['cit','fi','cp','imp','finmel']], ['Light and Darkness', ['ladr','bls','modc','bc','skull','ms']], ['Fiendsmith', ['eng','tract','lur','lac']], ['Hand traps and tech', ['ash','imperm','droll','drop']]];
const KTYPE = k => TYPE[SHORT[k]] || ({ladr:'spell',bls:'rit',modc:'rit',bsd:'eff',skull:'eff',drop:'spell',imperm:'trap'}[k]) || 'eff';
let hand = ['eng','tre','ash','droll','ogre'], example = true, shown = 0;

function lineHTML(L, opts = {}) {
  const tags = [];
  tags.push(`<span class="tag">${L.summons} Summons</span>`);
  if (L.impAt) tags.push(`<span class="tag ${L.impAt <= 5 ? 'good' : 'warn'}">Impasto Set at Summon ${L.impAt}</span>`);
  if (L.summons >= 5) tags.push(`<span class="tag ${L.impAt && L.impAt <= 5 ? 'good' : 'bad'}">Nibiru live from step ${L.fifth}${L.impAt && L.impAt <= 5 ? ' (Impasto answers it)' : ''}</span>`);
  const steps = L.steps.map(s => {
    const m = [];
    if (s.n) m.push(`<span class="sum">Summon ${s.from === s.to ? s.from : s.from + '–' + s.to}</span>`);
    if (s.tag === 'ash') m.push(`<span class="tag ${L.impAt && L.impAt < s.from ? 'good' : 'bad'}">${L.impAt && L.impAt < s.from ? 'Ash here → chain Impasto' : 'Ash / Imperm here ends the line'}</span>`);
    if (s.tag === 'ban') m.push('<span class="tag warn">random banish</span>');
    if (s.tag === 'imp') m.push('<span class="tag good">Impasto live from here</span>');
    return `<li><div style="min-width:0"><div class="do">${rich(s.t)}</div>${s.d && s.d.length ? `<ul class="how">${s.d.map(x => `<li>${rich(x)}</li>`).join('')}</ul>` : ''}${m.length ? `<div class="meta">${m.join('')}</div>` : ''}</div></li>`;
  }).join('');
  const keep = [...L.held.map(k => `hold ${chip(SHORT[k])}`), ...L.set.map(k => `Set ${chip(SHORT[k])}`), ...L.keep.filter(k => !L.held.includes(k) && !L.set.includes(k)).map(k => chip(SHORT[k]))];
  return `<div class="row">${tags.join('')}</div>
  <ol class="steps">${steps}</ol>
  <div class="two"><div style="display:grid;gap:6px"><span class="eyebrow">End board</span><div class="board">${L.board.map(b => `<span>${chipText(b)}</span>`).join('<span aria-hidden="true">·</span>')}</div>
  ${keep.length ? `<span class="eyebrow" style="margin-top:6px">Left in hand</span><div class="board">${keep.join(' ')}</div>` : ''}</div>
  <div style="display:grid;gap:6px"><span class="eyebrow">What it stops</span><ul class="plain">${L.stops.map(s => `<li>${esc(s)}</li>`).join('')}${L.held.length ? `<li>${L.held.length} hand trap${L.held.length > 1 ? 's' : ''} held</li>` : ''}</ul></div></div>
  ${L.notes.length ? L.notes.map(n => `<p class="note">${esc(n)}</p>`).join('') : ''}
  ${L.testHand ? `<p class="sum">This exact combination was replayed on the engine from: ${L.testHand.map(engName).map(chip).join(' ')}</p>` : (L.tested ? `<p class="sum">Engine test: <a href="#t-${L.tested}">${esc((TESTS.find(t => t.id === L.tested) || {}).title || L.tested)}</a></p>` : '')}`;
}
function renderHand() {
  const el = document.getElementById('hh-hand');
  el.innerHTML = Array.from({ length: HMAX() }, (_, i) => {
    const k = hand[i]; if (!k) return `<button class="slot" type="button" aria-label="Empty slot">empty</button>`;
    return `<button class="slot full" type="button" style="--k:var(--c-${KTYPE(k)})" data-i="${i}" aria-label="Remove ${esc(SHORT[k])}">${esc(SHORT[k])}</button>`;
  }).join('');
  document.getElementById('hh-ex').hidden = !example;
  el.querySelectorAll('.slot.full').forEach(b => b.onclick = () => { hand.splice(+b.dataset.i, 1); example = false; update(); });
  document.querySelectorAll('.pick').forEach(b => { const k = b.dataset.k; const used = hand.filter(x => x === k).length; b.disabled = used >= COUNT[k] || hand.length >= HMAX(); b.querySelector('small').textContent = `${used}/${COUNT[k]}`; });
}
function renderOut() {
  const out = document.getElementById('hh-out');
  if (!hand.length) { out.innerHTML = '<p class="lede">Add cards to see the line.</p>'; return; }
  const res = analyze(hand, second);
  if (!res.length) { out.innerHTML = `<h3>No tested line</h3><p>This hand has no Medius route and no Fiendsmith piece. Set every Spell/Trap you can use, Set Mind Shuffle, and hold your hand traps. ${hand.length < HMAX() ? 'Add more cards: the helper re-checks as you go.' : ''}</p>${solverPanel()}`; wireSolver(); return; }
  if (shown >= res.length) shown = 0;
  const L = res[shown];
  out.innerHTML = `<div style="display:grid;gap:4px"><span class="eyebrow">${shown === 0 ? 'Best line' : 'Other line'}</span><h3 style="font-size:20px">${esc(L.title)}</h3></div>${lineHTML(L)}${solverPanel()}
   ${res.length > 1 ? `<div class="alts"><span class="eyebrow">This hand can also play</span>${res.map((r, i) => i === shown ? '' : `<button class="btn" type="button" data-alt="${i}">${esc(r.title)} · ${r.summons} Summons</button>`).join('')}</div>` : ''}`;
  out.querySelectorAll('[data-alt]').forEach(b => b.onclick = () => { shown = +b.dataset.alt; renderOut(); out.scrollIntoView({ block: 'start' }); });
  wireSolver();
}
function update() { shown = 0; renderHand(); renderOut(); }
function buildPicker() {
  document.getElementById('hh-pick').innerHTML = GROUPS.map(([g, ks]) => `<div class="pgroup"><span class="eyebrow">${g}</span><div class="pgrid">${ks.map(k => `<button class="pick" type="button" data-k="${k}" style="--k:var(--c-${KTYPE(k)})">${esc(SHORT[k])}<small></small></button>`).join('')}</div></div>`).join('');
  document.querySelectorAll('.pick').forEach(b => b.onclick = () => { if (hand.length < HMAX()) { hand.push(b.dataset.k); example = false; update(); } });
}
